def f(I):
    cnt=collections.Counter(v for r in I for v in r)
    dom=cnt.most_common(1)[0][0]
    L=max((v for v in cnt if v!=dom),key=lambda v:cnt[v])
    lrows=[r for r in range(len(I)) if collections.Counter(I[r]).most_common(1)[0][0]==L]
    lcols=[c for c in range(len(I[0])) if collections.Counter([I[r][c] for r in range(len(I))]).most_common(1)[0][0]==L]
    dotcols=[c for c in lcols if any(I[r][c]!=L for r in lrows)]
    drows=[r for r in lrows if any(I[r][c]!=L for c in dotcols)]
    out=[]
    for i in range(len(drows)-1):
        row=[]
        for j in range(len(dotcols)-1):
            cs={(drows[i],dotcols[j]),(drows[i],dotcols[j+1]),(drows[i+1],dotcols[j]),(drows[i+1],dotcols[j+1])}
            vals={I[r][c] for r,c in cs}
            row.append(next(iter(vals)) if len(vals)==1 and next(iter(vals))!=L else dom)
        out.append(row)
    return out
